40	    fn get_or_insert_with<'a>(
41	        &self,
42	        key: &AtlasKey,
43	        build: &mut dyn FnMut() -> Result<Option<(Size<DevicePixels>, Cow<'a, [u8]>)>>,
44	    ) -> Result<Option<AtlasTile>> {
45	        let mut lock = self.0.lock();
46	        if let Some(tile) = lock.tiles_by_key.get(key) {
47	            Ok(Some(*tile))
48	        } else {
49	            let Some((size, bytes)) = build()? else {
50	                return Ok(None);
51	            };
52	            let tile = lock
53	                .allocate(size, key.texture_kind())
54	                .context("failed to allocate")?;
55	            let texture = lock.texture(tile.texture_id);
56	            texture.upload(tile.bounds, &bytes);
57	            lock.tiles_by_key.insert(key.clone(), tile);
58	            Ok(Some(tile))
59	        }
60	    }
61	
62	    fn remove(&self, key: &AtlasKey) {
63	        let mut lock = self.0.lock();
64	        let Some(tile) = lock.tiles_by_key.remove(key) else {
65	            return;
66	        };
67	        let id = tile.texture_id;
68	
69	        let textures = match id.kind {
70	            AtlasTextureKind::Monochrome => &mut lock.monochrome_textures,
71	            AtlasTextureKind::Polychrome => &mut lock.polychrome_textures,
72	            AtlasTextureKind::Subpixel => unreachable!(),
73	        };
74	
75	        let Some(texture_slot) = textures
76	            .textures
77	            .iter_mut()
78	            .find(|texture| texture.as_ref().is_some_and(|v| v.id == id))
79	        else {
80	            return;
81	        };
82	
83	        if let Some(mut texture) = texture_slot.take() {
84	            texture.allocator.deallocate(tile.tile_id.into());
85	            texture.decrement_ref_count();
86	            if texture.is_unreferenced() {
87	                textures.free_list.push(id.index as usize);
88	            } else {
89	                *texture_slot = Some(texture);
90	            }
91	        }
92	    }
93	}
